def _rewrite_feature_links(body: str, feature_id: str) -> str:
    """Rewrite intra-doc links in a copied feature markdown file from the source
    `docs/` layout to the flattened per-feature site layout.

    Skill-authored markdown links target the original tree (e.g. `./REQUIREMENTS.md`,
    `../../stories/<id>.md`, `../../design/<id>/screens/x.html`). The site builder
    relocates + lowercases those files into `features/<id>/` and copies the design
    bundle under `features/<id>/design/`, so the inline links must be remapped or
    MkDocs flags every one as a dangling reference.

    Only the target inside a markdown `](target)` is touched; link text, anchors,
    and query strings are preserved. Absolute URLs (`http`, `mailto`, `#`-only) and
    ADR links (`../../adr/...` already resolves in the site tree) are left untouched.
    """
    fid = re.escape(feature_id)
    # (pattern applied to the path portion of the link target, replacement)
    rules: list[tuple[str, str]] = [
        # same-dir feature files — case-folded on copy
        (r"^\./REQUIREMENTS\.md$", "requirements.md"),
        (r"^\./PLAN\.md$", "plan.md"),
        (r"^\./DESIGN\.md$", "design.md"),
        (r"^\./REVIEW\.md$", "review.md"),
        # story / research relocated into the feature dir
        (rf"^(?:\.\./\.\./|docs/)stories/{fid}\.md$", "story.md"),
        (rf"^(?:\.\./\.\./|docs/)research/{fid}\.md$", "research.md"),
        # long-path forms of the same-feature artefacts
        (rf"^(?:\.\./\.\./|docs/)features/{fid}/REQUIREMENTS\.md$", "requirements.md"),
        (rf"^(?:\.\./\.\./|docs/)features/{fid}/PLAN\.md$", "plan.md"),
        (rf"^(?:\.\./\.\./|docs/)features/{fid}/DESIGN\.md$", "design.md"),
        (rf"^(?:\.\./\.\./|docs/)features/{fid}/REVIEW\.md$", "review.md"),
        # design export bundle copied under features/<id>/design/ — prefix rewrite
        (rf"^(?:\.\./\.\./|docs/)design/{fid}/", "design/"),
    ]

    def rewrite_target(target: str) -> str:
        # split off #anchor / ?query so rules match the bare path
        frag = ""
        for sep in ("#", "?"):
            if sep in target:
                idx = target.index(sep)
                target, frag = target[:idx], target[idx:] + frag
        for pat, sub in rules:
            new = re.sub(pat, sub, target)
            if new != target:
                return new + frag
        return target + frag

    def repl(m: re.Match) -> str:
        target = m.group(1).strip()
        # leave external / absolute / anchor-only links alone
        if target.startswith(("http://", "https://", "mailto:", "#", "/")):
            return m.group(0)
        return f"]({rewrite_target(target)})"

    return re.sub(r"\]\(([^)\s]+)\)", repl, body)


@dataclass
class BuildResult:
    out_dir: Path
    site_dir: Path
    files_written: int
    mkdocs_built: bool


def build_site(
    *,
    root: Path,
    out: Path,
    include_internal: bool = False,
    clean: bool = False,
    strict: bool = False,
    do_build: bool = True,
    logo: Path | None = None,
    favicon: Path | None = None,
    kpi_window_days: int = 7,
) -> BuildResult:
    """Generate the MkDocs source tree under `out/` and (optionally) run mkdocs build.

    Layout written under `out/`:
      mkdocs.yml
      docs/
        index.md
        status.md
        rtm.md                                  (if RTM exists)
        features/
          index.md
          <id>/
            index.md story.md research.md requirements.md plan.md
            validation.md review.md tests.md design.md runbooks.md
        adr/
          index.md
          <NNNN>-<slug>.md
        sessions/
          index.md
          <YYYY-MM-DD>.md
        config/
          index.md
          <name>.md                              (each YAML wrapped in fence)
        reference/
          rules.md                               (only when include_internal)
      site/                                      (HTML output; created by mkdocs build)
    """
    snap = discover(root)
    out = out.resolve()

    if clean and out.exists():
        shutil.rmtree(out)

    docs_dir = out / "docs"
    docs_dir.mkdir(parents=True, exist_ok=True)

    # Jinja env scoped to the site templates dir
    tmpl_dir = Path(__file__).parent / "templates"
    env = Environment(
        loader=FileSystemLoader(str(tmpl_dir)),
        autoescape=False,
        undefined=StrictUndefined,
        keep_trailing_newline=True,
    )

    written: set[Path] = set()
    files_written = 0

    # 1. Home page
    home_body = _render_index(env, snap)
    files_written += _write(docs_dir / "index.md", home_body, written)

    # 2. Status board
    sorted_features = [snap.features[fid] for fid in sorted(snap.features)]
    state_table = render_state_table(sorted_features)
    status_tmpl = env.get_template("status.md.j2")
    files_written += _write(
        docs_dir / "status.md",
        status_tmpl.render(state_table=state_table),
        written,
    )

    # 3. RTM (copy verbatim)
    if snap.rtm_path:
        files_written += _write(docs_dir / "rtm.md", snap.rtm_path.read_text(encoding="utf-8"), written)

    # 4. Features index + per-feature dashboards + per-feature artifact pages
    if sorted_features:
        feat_idx_tmpl = env.get_template("features_index.md.j2")
        files_written += _write(
            docs_dir / "features" / "index.md",
            feat_idx_tmpl.render(
                feature_count=len(sorted_features),
                features=sorted_features,
                status_signal=compute_status_signal,
            ),
            written,
        )

        dash_tmpl = env.get_template("feature_dashboard.md.j2")
        tests_tmpl = env.get_template("tests.md.j2")
        simple_idx_tmpl = env.get_template("simple_index.md.j2")
        for fs in sorted_features:
            fdir = docs_dir / "features" / fs.feature_id
            fdir.mkdir(parents=True, exist_ok=True)

            files_written += _write(
                fdir / "index.md",
                _render_feature_dashboard(dash_tmpl, fs),
                written,
            )

            for src, dest in (
                (fs.story_path, "story.md"),
                (fs.research_path, "research.md"),
                (fs.requirements_path, "requirements.md"),
                (fs.plan_path, "plan.md"),
                (fs.validation_path, "validation.md"),
                (fs.review_path, "review.md"),
                # Evidence-pass companions: per-round table + escalation report.
                # Filenames are lowercased in the rendered tree for URL consistency
                # with the other rendered files (evidence.md, decisions.md, etc.).
                (fs.evidence_rounds_path, "evidence-rounds.md"),
                (fs.evidence_escalation_path, "evidence-escalation.md"),
            ):
                if src and src.exists():
                    files_written += _write(
                        fdir / dest,
                        _rewrite_feature_links(src.read_text(encoding="utf-8"), fs.feature_id),
                        written,
                    )

            if fs.test_cases_path and fs.test_cases_path.exists():
                files_written += _write(
                    fdir / "tests.md",
                    tests_tmpl.render(
                        feature_id=fs.feature_id,
                        tests_markdown=render_testcases_md(fs.test_cases_path),
                    ),
                    written,
                )

            # State-driven pages (decisions / clarifications / flags). Each is
            # emitted only when the corresponding state array is non-empty.
            decisions = fs.raw.get("decisions") or []
            if decisions:
                files_written += _write(
                    fdir / "decisions.md",
                    f"# {fs.feature_id} — Decisions\n\n" + render_decisions_md(decisions),
                    written,
                )

            clarifications = fs.raw.get("clarifications") or []
            if clarifications:
                files_written += _write(
                    fdir / "clarifications.md",
                    f"# {fs.feature_id} — Clarifications\n\n" + render_clarifications_md(clarifications),
                    written,
                )

            agent_flags = fs.raw.get("agent_flags") or []
            if agent_flags:
                files_written += _write(
                    fdir / "flags.md",
                    f"# {fs.feature_id} — Agent flags\n\n" + render_agent_flags_md(agent_flags),
                    written,
                )

            # Implementation evidence (written by evidence-pass skill at end of
            # /arh-implement Step 1). Surfaces the six-dimension packet plus inline
            # tails of FAILing dimension logs. Log files are copied verbatim into
            # the rendered site so engineers can view the full audit trail.
            impl_evidence = fs.raw.get("impl_evidence")
            if impl_evidence and impl_evidence.get("checks"):
                log_tails: dict[str, str] = {}
                log_links: dict[str, str] = {}
                evidence_assets = fdir / "evidence"
                checks_map = impl_evidence.get("checks") or {}
                for dim, info in checks_map.items():
                    ev_path_str = (info or {}).get("evidence_path")
                    if not ev_path_str:
                        continue
                    src_log = snap.root / ev_path_str
                    if not src_log.exists() or not src_log.is_file():
                        continue
                    evidence_assets.mkdir(parents=True, exist_ok=True)
                    dest_log = evidence_assets / src_log.name
                    shutil.copy2(src_log, dest_log)
                    written.add(dest_log.resolve())
                    files_written += 1
                    log_links[dim] = f"evidence/{src_log.name}"
                    if (info or {}).get("status") == "FAIL":
                        try:
                            lines = src_log.read_text(
                                encoding="utf-8", errors="replace"
                            ).splitlines()
                            log_tails[dim] = "\n".join(lines[-20:])
                        except OSError:
                            log_tails[dim] = "_log tail unavailable_"
                # Compute the set of flag ids that ACTUALLY exist in
                # state.agent_flags[] for this feature. The evidence adapter
                # links to flags.md#AF-NN only when the id is present here;
                # otherwise it falls back to plain text + "pending /arh-human-review"
                # to avoid 404 cross-links during the window between
                # evidence-pass writing flag_ids and /arh-human-review bundling.
                available_flag_ids = {
                    f.get("flag_id")
                    for f in (fs.raw.get("agent_flags") or [])
                    if f.get("flag_id")
                }
                # Related-artefact line: when EVIDENCE-ROUNDS.md or
                # EVIDENCE-ESCALATION.md exist for this feature, link them at
                # the top of evidence.md so the engineer can jump straight to
                # the fix-loop history or the persistent-failure report.
                related_bits = []
                if fs.evidence_rounds_path:
                    related_bits.append(
                        "[Round table](evidence-rounds.md) — per-round history of the internal fix loop"
                    )
                if fs.evidence_escalation_path:
                    related_bits.append(
                        "[Escalation report](evidence-escalation.md) — round-3 persistent-failure detail"
                    )
                related_section = ""
                if related_bits:
                    related_section = "## Related\n\n" + "\n".join(
                        f"- {b}" for b in related_bits
                    ) + "\n\n"
                files_written += _write(
                    fdir / "evidence.md",
                    f"# {fs.feature_id} — Implementation evidence\n\n"
                    + related_section
                    + render_impl_evidence_md(
                        impl_evidence,
                        log_tails=log_tails,
                        log_links=log_links,
                        available_flag_ids=available_flag_ids,
                    ),
                    written,
                )

            # DESIGN.md page: render the ux-agent-authored file (when present)
            # PLUS list the per-feature export bundle assets at docs/design/<id>/
            # (when present). Either source alone is sufficient to emit the page.
            design_body_parts: list[str] = []
            if fs.design_path and fs.design_path.exists():
                design_body_parts.append(
                    _rewrite_feature_links(fs.design_path.read_text(encoding="utf-8"), fs.feature_id)
                )

            if fs.design_dir and fs.design_dir.is_dir():
                # Copy bundle assets verbatim into the site tree, preserving
                # subdirectory layout (e.g. screens/<name>-<form>.html).
                design_assets_root = fdir / "design"
                items: list[dict] = []
                for asset in sorted(fs.design_dir.rglob("*")):
                    if asset.is_file():
                        rel = asset.relative_to(fs.design_dir)
                        target = design_assets_root / rel
                        target.parent.mkdir(parents=True, exist_ok=True)
                        shutil.copy2(asset, target)
                        written.add(target)
                        items.append({"label": str(rel), "href": f"design/{rel.as_posix()}"})
                if items:
                    asset_lines = ["## Export bundle", ""]
                    for it in items:
                        asset_lines.append(f"- [{it['label']}]({it['href']})")
                    design_body_parts.append("\n".join(asset_lines) + "\n")

            if design_body_parts:
                if fs.design_path and fs.design_path.exists():
                    # Already a complete markdown doc — append asset section below.
                    body = "\n\n".join(design_body_parts)
                else:
                    # No DESIGN.md → fall back to a simple index of the bundle.
                    body = simple_idx_tmpl.render(
                        title=f"{fs.feature_id} — Design assets",
                        description="Exported screens, prototypes, and reference material for this feature.",
                        items=items,
                    )
                files_written += _write(fdir / "design.md", body, written)

            if fs.runbook_paths:
                runbook_items = []
                for rb in fs.runbook_paths:
                    rb_target = fdir / "runbooks" / rb.name
                    rb_target.parent.mkdir(parents=True, exist_ok=True)
                    _write(rb_target, rb.read_text(encoding="utf-8"), written)
                    files_written += 1
                    runbook_items.append({"label": rb.stem, "href": f"runbooks/{rb.name}"})
                files_written += _write(
                    fdir / "runbooks.md",
                    simple_idx_tmpl.render(
                        title=f"{fs.feature_id} — Runbooks",
                        description=None,
                        items=runbook_items,
                    ),
                    written,
                )

    # 5. ADRs
    if snap.adr_paths:
        adr_dir = docs_dir / "adr"
        adr_dir.mkdir(parents=True, exist_ok=True)
        adr_records = []
        for p in snap.adr_paths:
            files_written += _write(adr_dir / p.name, p.read_text(encoding="utf-8"), written)
            adr_records.append(_adr_record(p))
        idx_tmpl = env.get_template("adr_index.md.j2")
        files_written += _write(
            adr_dir / "index.md",
            idx_tmpl.render(adr_count=len(adr_records), adrs=adr_records),
            written,
        )

    # 6. Sessions
    if snap.session_paths:
        sess_dir = docs_dir / "sessions"
        sess_dir.mkdir(parents=True, exist_ok=True)
        items = []
        for p in snap.session_paths:
            files_written += _write(sess_dir / p.name, p.read_text(encoding="utf-8"), written)
            items.append({"label": p.stem, "href": p.name})
        idx_tmpl = env.get_template("simple_index.md.j2")
        files_written += _write(
            sess_dir / "index.md",
            idx_tmpl.render(
                title="Sessions",
                description="Work session logs (one per day).",
                items=items,
            ),
            written,
        )

    # 7. Config (YAML wrapped in fenced blocks)
    if snap.config_paths:
        cfg_dir = docs_dir / "config"
        cfg_dir.mkdir(parents=True, exist_ok=True)
        items = []
        for p in snap.config_paths:
            body = f"# {p.stem}\n\n```yaml\n{p.read_text(encoding='utf-8').rstrip()}\n```\n"
            md_name = p.stem + ".md"
            files_written += _write(cfg_dir / md_name, body, written)
            items.append({"label": p.stem, "href": md_name})
        idx_tmpl = env.get_template("simple_index.md.j2")
        files_written += _write(
            cfg_dir / "index.md",
            idx_tmpl.render(
                title="Configuration",
                description="Provider configs (issue tracker, doc tracker, project commands).",
                items=items,
            ),
            written,
        )

    # 8. Internal rules
    if include_internal and snap.rule_paths:
        ref_dir = docs_dir / "reference"
        ref_dir.mkdir(parents=True, exist_ok=True)
        rules = []
        for p in snap.rule_paths:
            title = p.stem.replace("-", " ").capitalize()
            rules.append(
                {
                    "title": title,
                    "relative_path": str(p.relative_to(snap.root)),
                    "body": p.read_text(encoding="utf-8").lstrip(),
                }
            )
        idx_tmpl = env.get_template("rules.md.j2")
        files_written += _write(ref_dir / "rules.md", idx_tmpl.render(rules=rules), written)

    # 8a. Activity feed + KPI dashboard (only when docs/activity/*.jsonl exists)
    if snap.activity_paths:
        from datetime import datetime, timedelta

        entries = parse_all_activity(snap.activity_paths)
        now = datetime.now(UTC)
        since = now - timedelta(days=kpi_window_days)

        # Activity feed (group by user)
        by_user_map = group_entries_by_user(entries, since=since)
        # Stable ordering: most-active user first
        by_user = sorted(by_user_map.items(), key=lambda kv: len(kv[1]), reverse=True)
        user_totals = {
            u: _humanize_seconds(sum(e.duration_s for e in rows)) for u, rows in by_user
        }
        # Feature ids with a rendered page (features/<id>/index.md). Activity and
        # KPI rows only linkify these; ids that appear in the activity log but have
        # no feature dir (orphans) render as plain text to avoid dangling links.
        rendered_feature_ids = set(snap.features.keys())

        activity_tmpl = env.get_template("activity.md.j2")
        files_written += _write(
            docs_dir / "activity.md",
            activity_tmpl.render(
                by_user=by_user,
                user_totals=user_totals,
                window_label=f"last {kpi_window_days} days",
                outcome_icon=render_outcome_icon,
                intervention_marker=render_intervention_marker,
                feature_ids=rendered_feature_ids,
            ),
            written,
        )

        # KPI dashboard
        validation_summaries: dict[str, str] = {}
        for fid, fs in snap.features.items():
            if fs.validation_path and fs.validation_path.exists():
                validation_summaries[fid] = fs.validation_path.read_text(encoding="utf-8")
        # Two-tier state: per-feature records (post-plan) hold P-tier fields like
        # validation_summary + pending_carry_forward; index entries (pre-plan)
        # don't. Build a unified record map keyed by feature_id where the
        # per-feature record wins when present; fall back to the index entry.
        state_records: dict[str, dict] = {}
        for fid, fs in snap.features.items():
            state_records[fid] = fs.raw or {}
        # Include any index-only ids that aren't in snap.features (defensive).
        for fid, rec in snap.state_raw.items():
            if fid not in state_records and isinstance(rec, dict):
                state_records[fid] = rec
        k = compute_kpi_window(
            entries,
            window_days=kpi_window_days,
            now=now,
            state_raw=state_records,
            validation_summaries=validation_summaries,
        )
        totals = compute_project_totals(entries)
        kpi_tmpl = env.get_template("kpi.md.j2")
        files_written += _write(
            docs_dir / "kpi.md",
            kpi_tmpl.render(
                k=k, totals=totals, pricing=pricing_reference(), feature_ids=rendered_feature_ids
            ),
            written,
        )

    # 8b. Branding (logo + favicon) — copied into docs/assets/. When the
    #     caller does not supply paths, fall back to the bundled Apexon assets
    #     under src/harness/site/branding/.
    branding_dir = Path(__file__).parent / "branding"
    effective_logo = logo if logo else branding_dir / "apexon-logo.svg"
    effective_favicon = favicon if favicon else branding_dir / "apexon.png"

    logo_rel: str | None = None
    favicon_rel: str | None = None
    if effective_logo.exists():
        assets_dir = docs_dir / "assets"
        assets_dir.mkdir(parents=True, exist_ok=True)
        target = assets_dir / effective_logo.name
        shutil.copy2(effective_logo, target)
        written.add(target.resolve())
        files_written += 1
        logo_rel = f"assets/{effective_logo.name}"
    if effective_favicon.exists():
        assets_dir = docs_dir / "assets"
        assets_dir.mkdir(parents=True, exist_ok=True)
        target = assets_dir / effective_favicon.name
        shutil.copy2(effective_favicon, target)
        written.add(target.resolve())
        files_written += 1
        favicon_rel = f"assets/{effective_favicon.name}"

    # 9. mkdocs.yml
    nav = build_nav(snap, include_internal=include_internal)
    nav_yaml = yaml.safe_dump(nav, sort_keys=False, default_flow_style=False, indent=2)
    # Indent the nav YAML two spaces to nest under the `nav:` key
    nav_yaml_indented = "\n".join("  " + line if line else "" for line in nav_yaml.splitlines())
    mkdocs_tmpl = env.get_template("mkdocs.yml.j2")
    mkdocs_yml = mkdocs_tmpl.render(
        project_title=snap.project_title,
        nav_yaml=nav_yaml_indented,
        strict=strict,
        logo=logo_rel,
        favicon=favicon_rel,
    )
    files_written += _write(out / "mkdocs.yml", mkdocs_yml, written)

    # 10. Custom stylesheet — hides the "Made with Material for MkDocs"
    #     copyright/generator line in the footer.
    extra_css = (
        "/* harness site overrides */\n"
        ".md-copyright__highlight { display: none; }\n"
        ".md-copyright a[href*='squidfunk.github.io/mkdocs-material'] { display: none; }\n"
    )
    files_written += _write(docs_dir / "stylesheets" / "extra.css", extra_css, written)

    # 11. .gitignore — ignore the entire output by default; user removes rules
    #     or adds explicit `!path` lines to commit any subset.
    gitignore_body = (
        "# harness site output — fully ignored by default. Edit this file to\n"
        "# whitelist specific files/dirs you want to commit, e.g.:\n"
        "#   !docs/\n"
        "#   !mkdocs.yml\n"
        "#   site/   # always ignore the mkdocs build output\n"
        "*\n"
        "!.gitignore\n"
    )
    files_written += _write(out / ".gitignore", gitignore_body, written)

    # 11. Prune stale files
    _prune_stale(out, written)

    # 12. mkdocs build
    site_dir = out / "site"
    mkdocs_built = False
    if do_build:
        mkdocs_built = _run_mkdocs_build(out / "mkdocs.yml", strict=strict)

    return BuildResult(
        out_dir=out, site_dir=site_dir, files_written=files_written, mkdocs_built=mkdocs_built
    )


def serve_site(out: Path, port: int = 8000) -> None:
    """Run `mkdocs serve` against `out/mkdocs.yml`. Blocks until Ctrl-C."""
    from mkdocs.commands.serve import serve as mkdocs_serve

    config_file = out / "mkdocs.yml"
    if not config_file.exists():
        raise FileNotFoundError(f"mkdocs.yml not found at {config_file}")
    mkdocs_serve(config_file=str(config_file), dev_addr=f"127.0.0.1:{port}")


# ----- internal helpers ---------------------------------------------------


def _render_index(env: Environment, snap: ProjectSnapshot) -> str:
    """Build the home page from CLAUDE.md (minus SDLC-commands stub)."""
    if snap.claude_md_path and snap.claude_md_path.exists():
        raw = snap.claude_md_path.read_text(encoding="utf-8")
        # Skip the H1 (we'll re-render it via project_title); strip blank lines after
        lines = raw.splitlines()
        body_lines = lines[1:] if lines and lines[0].startswith("# ") else lines
        # Description = first non-empty line after H1
        description = ""
        for line in body_lines:
            stripped = line.strip()
            if stripped:
                description = stripped
                # Skip this line from the body
                idx = body_lines.index(line)
                body_lines = body_lines[idx + 1:]
                break
        # Drop top-level @imports (they don't resolve in mkdocs); keep as a note
        body_no_imports = "\n".join(
            line for line in body_lines if not line.strip().startswith("@")
        )
    else:
        description = ""
        body_no_imports = ""

    tmpl = env.get_template("index.md.j2")
    return tmpl.render(
        project_title=snap.project_title,
        project_description=description or "Harness project.",
        claude_md_body=body_no_imports.strip(),
        feature_count=len(snap.features),
        adr_count=len(snap.adr_paths),
        session_count=len(snap.session_paths),
    )


def _render_feature_dashboard(tmpl, fs: FeatureState) -> str:
    """Synthesise the per-feature dashboard."""
    emoji, label = compute_status_signal(fs)
    admon_kind = {"✅": "success", "🟢": "success", "🟡": "info", "🚫": "danger", "⚪": "note"}.get(emoji, "note")

    story_excerpt = ""
    if fs.story_path and fs.story_path.exists():
        body = fs.story_path.read_text(encoding="utf-8")
        story_excerpt = extract_section(body, "User story", max_chars=400)

    research_summary = ""
    if fs.research_path and fs.research_path.exists():
        body = fs.research_path.read_text(encoding="utf-8")
        research_summary = extract_section(body, "Synthesis", max_chars=600)

    prd_summary = ""
    if fs.requirements_path and fs.requirements_path.exists():
        body = fs.requirements_path.read_text(encoding="utf-8")
        for heading in ("Outcome", "Summary", "Problem"):
            prd_summary = extract_section(body, heading, max_chars=500)
            if prd_summary:
                break

    r = fs.raw
    decisions = r.get("decisions") or []
    clarifications = r.get("clarifications") or []
    agent_flags = r.get("agent_flags") or []
    open_flag_count = sum(1 for f in agent_flags if f.get("status") == "open")
    open_clarification_count = sum(
        1 for c in clarifications if c.get("status") in ("asked", "partially-answered")
    )

    # Implementation evidence — six-dimension packet from evidence-pass skill.
    impl_evidence = r.get("impl_evidence") or {}
    evidence_checks = impl_evidence.get("checks") or {}
    evidence_pass_count = sum(
        1 for d in evidence_checks.values() if d.get("status") == "PASS"
    )
    evidence_fail_count = sum(
        1 for d in evidence_checks.values() if d.get("status") == "FAIL"
    )
    evidence_na_count = sum(
        1 for d in evidence_checks.values() if d.get("status") == "N/A"
    )
    evidence_total = len(evidence_checks)
    evidence_rounds = impl_evidence.get("rounds")
    if evidence_total == 0:
        evidence_verdict = ""  # not yet run
    elif evidence_fail_count > 0:
        evidence_verdict = "BLOCKED"
    else:
        evidence_verdict = "READY"

    links = {
        "story": "story.md" if fs.story_path else None,
        "research": "research.md" if fs.research_path else None,
        "requirements": "requirements.md" if fs.requirements_path else None,
        "plan": "plan.md" if fs.plan_path else None,
        "validation": "validation.md" if fs.validation_path else None,
        "review": "review.md" if fs.review_path else None,
        "tests": "tests.md" if fs.test_cases_path else None,
        "design": "design.md" if (fs.design_path or fs.design_dir) else None,
        "runbooks": "runbooks.md" if fs.runbook_paths else None,
        "decisions": "decisions.md" if decisions else None,
        "clarifications": "clarifications.md" if clarifications else None,
        "flags": "flags.md" if agent_flags else None,
        "evidence": "evidence.md" if evidence_total > 0 else None,
        "evidence_rounds": "evidence-rounds.md" if fs.evidence_rounds_path else None,
        "evidence_escalation": "evidence-escalation.md" if fs.evidence_escalation_path else None,
    }
    has_evidence_escalation = bool(fs.evidence_escalation_path)
    has_evidence_rounds = bool(fs.evidence_rounds_path)

    return tmpl.render(
        feature_id=fs.feature_id,
        feature_title=fs.title,
        status_signal=(emoji, label),
        admonition_kind=admon_kind,
        phase=r.get("phase", "—"),
        story_status=r.get("story", "—"),
        research_status=r.get("research", "—"),
        research_verdict=r.get("research_verdict", ""),
        prd_status=r.get("prd", "—"),
        gate=r.get("gate", ""),
        plan_status=r.get("plan", "—"),
        plan_validation=r.get("plan_validation", ""),
        impl_status=r.get("impl", "—"),
        review_status=r.get("review", "—"),
        tracker_key=r.get("tracker_key", ""),
        tracker_url=r.get("tracker_url", ""),
        story_excerpt=story_excerpt,
        research_summary=research_summary,
        prd_summary=prd_summary,
        links=links,
        decision_count=len(decisions),
        clarification_round_count=len(clarifications),
        open_clarification_count=open_clarification_count,
        agent_flag_count=len(agent_flags),
        open_flag_count=open_flag_count,
        evidence_total=evidence_total,
        evidence_pass_count=evidence_pass_count,
        evidence_fail_count=evidence_fail_count,
        evidence_na_count=evidence_na_count,
        evidence_rounds=evidence_rounds,
        evidence_verdict=evidence_verdict,
        has_evidence_rounds=has_evidence_rounds,
        has_evidence_escalation=has_evidence_escalation,
    )


def _adr_record(p: Path) -> dict:
    stem = p.stem
    number, _, slug = stem.partition("-")
    # Title from first H1 of the file when available
    title = slug.replace("-", " ").capitalize()
    try:
        first_line = p.read_text(encoding="utf-8").splitlines()[0]
        if first_line.startswith("# "):
            title = first_line[2:].strip()
    except Exception:
        pass
    return {"number": number, "slug": slug, "title": title, "filename": p.name}


def _write(path: Path, content: str, registry: set[Path]) -> int:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    registry.add(path.resolve())
    return 1


def _prune_stale(out: Path, written: set[Path]) -> None:
    """Remove files under out/ (except the `site/` build dir) not in `written`."""
    for path in out.rglob("*"):
        if not path.is_file():
            continue
        resolved = path.resolve()
        # Skip the mkdocs build output dir entirely
        try:
            resolved.relative_to((out / "site").resolve())
            continue
        except ValueError:
            pass
        if resolved not in written:
            path.unlink()
    # Drop empty dirs
    for d in sorted((p for p in out.rglob("*") if p.is_dir()), key=lambda p: len(p.parts), reverse=True):
        with contextlib.suppress(OSError):
            d.rmdir()


def _run_mkdocs_build(config_file: Path, *, strict: bool) -> bool:
    """Invoke mkdocs.commands.build.build in-process."""
    try:
        from mkdocs.commands.build import build as mkdocs_build
        from mkdocs.config import load_config
    except ImportError:
        print(
            "WARNING: mkdocs-material is not installed; emitting source only. "
            "Install with `pip install mkdocs-material` to render HTML.",
            file=sys.stderr,
        )
        return False

    cfg = load_config(config_file=str(config_file), strict=strict)
    mkdocs_build(cfg)
    return True
